/* Ironlog — loading: plates, bars, collars, the plate inventory, warm-up ramps,
   load rounding, and places with their kit. What a weight means on a real bar
   in a real gym. Split out of workout.js (ROADMAP E17 phase 2) so events,
   tools, bar speed and the coach can use it without importing the workout
   screen. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { $, U, dw, esc, fromKg, nice, roundBar, toKg, uid, wt } from './core.js';
import { save } from './database.js';
import { EQ_ICON, EQ_TITLE, catalogue, completeLeaf, displayName, keyLeaf, leafKey, leafName, movementById } from './exercises.js';
import { closeAllModals, closeModal, confirmDlg, modal, render, toast } from './kit.js';
import { S } from './state.js';
import { bust, statsFor } from './stats.js';
/* end imports */

/* ---------------- plates, bars, ramps, places ---------------- */
/* ---------------- warm-up ramp ----------------
   Builds a ladder to a target load: three warm-up sets at most, the empty bar
   counting as one. A session warm-up primes the working sets, it doesn't eat
   into them. Meet day (full: true) keeps the long ladder to an opener, where a
   bad warm-up costs you the number outright. */
const RAMP = {
  // two steps after the empty bar, three when the bar is skipped
  bar:    { pcts: [0.60, 0.80],       single: [3, 1],    low: [5, 3],    high: [6, 3],    rest: [75, 120] },
  nobar:  { pcts: [0.50, 0.70, 0.85], single: [5, 3, 1], low: [5, 3, 2], high: [8, 5, 3], rest: [60, 90, 120] },
  meet:   { pcts: [0.40, 0.55, 0.70, 0.80, 0.88, 0.94], single: [5, 3, 2, 1, 1, 1], rest: [60, 90, 120, 180, 210, 240] },
};
const RAMP_MAX = 3;
export function warmupRamp(targetKg, reps = 1, barKg = 20, round = roundBar, roundWork = round, { full = false } = {}) {
  if (!targetKg || targetKg <= 0) return [];
  const band = reps <= 2 ? 'single' : reps <= 6 ? 'low' : 'high';
  const out = [];

  if (barKg > 0 && targetKg > barKg * 1.5) {
    out.push({ kg: barKg, reps: reps <= 2 ? 8 : 10, rest: 45, bar: true });
  }
  const base = full ? RAMP.meet : out.length ? RAMP.bar : RAMP.nobar;
  const spec = { pcts: base.pcts, reps: base[band] || base.single, rest: base.rest };

  spec.pcts.forEach((p, i) => {
    if (!full && out.length >= RAMP_MAX) return;
    const kg = round(targetKg * p);
    if (kg <= barKg) return;                       // below the empty bar: skip
    if (out.some(x => Math.abs(x.kg - kg) < 0.01)) return;   // duplicate after rounding
    if (kg >= targetKg) return;                    // never warm up at or above the target
    out.push({ kg, reps: spec.reps[i], rest: spec.rest[i], pct: Math.round(p * 100) });
  });

  out.push({ kg: roundWork(targetKg), reps, rest: 0, work: true });
  return out;
}
function fmtRest(s) {
  if (!s) return '';
  return s >= 60 ? `${Math.round(s / 60)}${s % 60 ? `:${String(s % 60).padStart(2, '0')}` : ' min'}` : `${s}s`;
}
/* onAdd(warmups): from a live workout, "Add to workout" hands back the
   warm-up steps (not the work set) to go in ahead of the working sets. */
export function openRamp(name, presetKg, presetReps, onAdd) {
  let last = [];
  const st = statsFor(name);
  const suggestion = presetKg || (st ? roundBar(st.best.e1) : 0);
  const leaf = String(name).includes('/') ? keyLeaf(name) : null;
  const barred = !leaf || BAR_EQUIPMENT.includes(leaf.equipment);   // plates on a bar: round to what loads
  const bar0 = barred ? barFor(leaf) : null;

  const draw = (targetDisp, reps, barDisp) => {
    const barKg = toKg(barDisp), inv = inventory(), eff = barKg + collarPair();
    /* Warm-ups load from plain plates (2.5 kg and up): nobody wants 1.25s
       and 0.5s on a 60% single. The work set gets the whole inventory. */
    const plain = inv.filter(p => p.kg >= 2.5 - 1e-9);
    const round = barred ? (kg => loadableNear(kg, eff, plain.length ? plain : inv)) : (kg => roundLoadFor(kg, leaf));
    const roundWork = barred ? (kg => loadableNear(kg, eff, inv)) : round;
    const ramp = warmupRamp(toKg(targetDisp), reps, barKg, round, roundWork);
    last = ramp;
    if (!ramp.length) return `<div class="sub">Enter a target weight.</div>`;
    return `<table class="settable"><thead><tr>
        <th class="c-set">#</th><th>${U()}</th><th>Reps</th><th>Rest</th></tr></thead><tbody>
      ${ramp.map((r, i) => `<tr class="${r.work ? 'pr' : ''}">
        <td class="c-set"><div class="setno ${r.work ? '' : 'warm'}">${r.work ? '★' : r.bar ? 'B' : i}</div></td>
        <td class="mono"><b>${nice(dw(r.kg))}</b>${r.bar ? ' <span class="dimmer">bar</span>' : r.pct ? ` <span class="dimmer">${r.pct}%</span>` : ''}
          ${barred && !r.bar ? `<div class="dimmer" style="font-size:10.5px">${esc(plateLine(r.kg, eff, inv))}</div>` : ''}</td>
        <td class="mono">${r.reps}</td>
        <td class="mono dimmer">${r.work ? '—' : fmtRest(r.rest)}</td>
      </tr>`).join('')}
    </tbody></table>`;
  };
  const barDisp0 = nice(dw(bar0 ? bar0.kg : (S.settings.barKg || 20)));

  modal({
    title: `Warm-up · ${leafName(name)}`,
    body: `
      <div class="row" style="gap:8px">
        <div class="field grow"><label>Target (${U()})</label>
          <input type="number" step="0.5" inputmode="decimal" id="rTarget" value="${suggestion ? dw(suggestion) : ''}"></div>
        <div class="field" style="width:80px"><label>Reps</label>
          <input type="number" inputmode="numeric" id="rReps" value="${presetReps > 0 ? presetReps : 1}"></div>
        <div class="field" style="width:88px"><label>Bar (${U()})</label>
          <input type="number" step="0.5" inputmode="decimal" id="rBar" value="${barDisp0}"></div>
      </div>
      ${bar0 ? `<div class="sub" style="margin:-4px 0 8px">${esc(bar0.name)}${collarPair() ? ` · collars ${wt(collarPair() / 2, 2)} each` : ''}${barred ? ' · steps rounded to plates you have' : ''}</div>` : ''}
      <div id="rOut">${draw(suggestion ? dw(suggestion) : 0, presetReps > 0 ? presetReps : 1, barDisp0)}</div>
      <div class="sub" style="margin-top:9px">Rest is a floor, not a target — on the last two steps take longer if you need it.</div>
    `,
    foot: onAdd ? `<button class="btn ghost" data-close>Close</button><button class="btn primary" id="rAdd">Add to workout</button>`
      : `<button class="btn primary" data-close>Done</button>`,
    onOpen: bg => {
      const add = $('#rAdd', bg);
      if (add) add.onclick = () => {
        const w = last.filter(r => !r.work);
        if (!w.length) return toast(last.length ? 'Too light to need a warm-up' : 'Enter a target weight first');
        closeModal(); onAdd(w);
      };
      const upd = () => {
        const bar = +$('#rBar', bg).value || 20;
        if (!bar0 || bar0.isDefault) { S.settings.barKg = toKg(bar); save(); }   // a plain barbell remembers; a tagged bar lives in Settings
        $('#rOut', bg).innerHTML = draw(+$('#rTarget', bg).value || 0, +$('#rReps', bg).value || 1, bar);
      };
      ['#rTarget', '#rReps', '#rBar'].forEach(s => { $(s, bg).oninput = upd; });
    },
  });
}
/* ---------------- plate maths ----------------
   Works from a real inventory, in pairs, because a stack you can't build is
   worse than no answer. If the target isn't loadable it says so and gives the
   nearest weight you can actually make in both directions. */
const DEFAULT_PLATES = [
  { kg: 25, pairs: 4 }, { kg: 20, pairs: 4 }, { kg: 15, pairs: 2 },
  { kg: 10, pairs: 4 }, { kg: 5, pairs: 2 }, { kg: 2.5, pairs: 2 },
  { kg: 1.25, pairs: 2 }, { kg: 0.5, pairs: 2 },
];
/* Bars carry the equipment they're for, so a trap-bar deadlift loads from the
   trap bar and a log press from the log without asking. Presets are starting
   points — real bars vary, so each one is editable in Settings. */
const BAR_EQUIPMENT = ['barbell', 'safety_squat_bar', 'trap_bar', 'axle', 'log', 'cambered_bar', 'swiss_bar'];
export const BAR_PRESETS = [
  { name: 'Barbell', kg: 20, eq: 'barbell' }, { name: "Women's bar", kg: 15, eq: '' },
  { name: 'Deadlift bar', kg: 20, eq: '' }, { name: 'Safety squat bar', kg: 30, eq: 'safety_squat_bar' },
  { name: 'Trap bar', kg: 25, eq: 'trap_bar' }, { name: 'Axle', kg: 20, eq: 'axle' }, { name: 'Log', kg: 50, eq: 'log' },
  { name: 'Cambered bar', kg: 25, eq: 'cambered_bar' }, { name: 'Swiss bar', kg: 18, eq: 'swiss_bar' },
];
/* The bar for a lift: one tagged with its equipment, else the preset for that
   equipment (flagged, so the sheet can say it's a guess), else the usual bar. */
export function barFor(leaf) {
  const bl = bars(), eq = leaf && leaf.equipment;
  const tagged = eq && bl.find(b => b.eq === eq);
  if (tagged) return tagged;
  if (eq && eq !== 'barbell') { const p = BAR_PRESETS.find(b => b.eq === eq); if (p) return { ...p, preset: true }; }
  const pl = curPlace(), own = pl && pl.bars && pl.bars.length;
  const usual = (own ? null : bl.find(b => Math.abs(b.kg - (S.settings.barKg || 20)) < 1e-9)) || bl[0];
  return { ...usual, isDefault: true };
}
/* Both collars together; they ride on every loaded bar. */
export function collarPair() {
  const pl = curPlace(), c = pl && pl.plates && pl.plates.length ? pl.collarKg : S.settings.collarKg;
  return (c > 0 ? c : 0) * 2;
}
/* Nearest weight the inventory can build on this bar; a tie goes to the lighter. */
export function loadableNear(kg, barKg, inv) {
  const n = nearestLoadable(kg, barKg, inv);
  if (n.below == null) return n.above == null ? kg : n.above;
  if (n.above == null) return n.below;
  return kg - n.below <= n.above - kg ? n.below : n.above;
}
/* "20 + 5 + 1.25 a side" */
export function plateLine(kg, barKg, inv) {
  const r = loadPlates(kg, barKg, inv);
  if (r.impossible || !r.perSide.length) return r.impossible ? '' : 'empty bar';
  return r.perSide.flatMap(p => Array(p.count).fill(String(dw(p.kg, 2)))).join(' + ') + ' a side';
}
/* One editable bar row in Settings. */
const BAR_FOR = [['', 'For: —'], ['barbell', 'Barbell'], ['safety_squat_bar', 'SSB'], ['trap_bar', 'Trap'], ['axle', 'Axle'], ['log', 'Log'], ['cambered_bar', 'Cambered'], ['swiss_bar', 'Swiss']];
export function barRow(k, b) {
  return `<div class="row" style="gap:6px;margin-bottom:6px">
    <input class="grow" data-bn="${k}" value="${esc(b.name || '')}" placeholder="name" aria-label="Bar name" style="min-width:0">
    <input type="number" step="0.5" inputmode="decimal" data-bk="${k}" value="${b.kg ? nice(dw(b.kg)) : ''}" placeholder="${U()}" aria-label="Bar weight" style="width:64px">
    <select data-be="${k}" aria-label="Used for" style="width:96px">${BAR_FOR.map(([v, l]) => `<option value="${v}" ${(b.eq || '') === v ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <button class="btn sm ghost" data-brm="${k}" aria-label="Remove bar">−</button>
  </div>`;
}
/* The main inventory (Settings), and the one in use: the current place's own
   when it has one (D6), else the main. */
export function mainPlates() {
  const inv = S.settings.plates && S.settings.plates.length ? S.settings.plates : DEFAULT_PLATES;
  return inv.filter(p => p.kg > 0 && p.pairs > 0).sort((a, b) => b.kg - a.kg);
}
export function mainBars() {
  return (S.settings.bars && S.settings.bars.length ? S.settings.bars : [{ name: 'Barbell', kg: 20 }])
    .filter(b => b.kg > 0);
}
export function inventory() {
  const pl = curPlace();
  return pl && pl.plates && pl.plates.length ? pl.plates.filter(p => p.kg > 0 && p.pairs > 0).sort((a, b) => b.kg - a.kg) : mainPlates();
}
function bars() {
  const pl = curPlace();
  return pl && pl.bars && pl.bars.length ? pl.bars.filter(b => b.kg > 0) : mainBars();
}
/* Greedy is optimal here: every plate set in use is "canonical" (each size at
   least twice the next), so taking the heaviest that fits never strands you. */
export function loadPlates(targetKg, barKg, inv) {
  const side = (targetKg - barKg) / 2;
  if (side < 0) return { impossible: 'under', bar: barKg };
  if (side === 0) return { perSide: [], achieved: barKg, exact: true, bar: barKg };

  let left = side;
  const perSide = [];
  inv.forEach(p => {
    const n = Math.min(p.pairs, Math.floor((left + 1e-9) / p.kg));
    if (n > 0) { perSide.push({ kg: p.kg, count: n }); left -= n * p.kg; }
  });

  if (left > 1e-9) {
    /* Greedy only stops short when the set isn't canonical (25/20/15/10 isn't,
       and neither is a 1 kg plate beside 1.25) or pairs run out. Then search:
       the heaviest reachable per-side load, fewest plates on a tie. */
    let best = { sum: side - left, n: perSide.reduce((a, p) => a + p.count, 0), pick: [...perSide] };
    const walk = (i, sum, n, pick) => {
      if (sum > side + 1e-9) return;
      if (sum > best.sum + 1e-9 || (Math.abs(sum - best.sum) < 1e-9 && n < best.n)) best = { sum, n, pick: [...pick] };
      if (i >= inv.length || Math.abs(sum - side) < 1e-9) return;
      for (let c = Math.min(inv[i].pairs, Math.floor((side - sum + 1e-9) / inv[i].kg)); c >= 0; c--) {
        if (c) pick.push({ kg: inv[i].kg, count: c });
        walk(i + 1, sum + c * inv[i].kg, n + c, pick);
        if (c) pick.pop();
      }
    };
    walk(0, 0, 0, []);
    perSide.length = 0; perSide.push(...best.pick);
    left = side - best.sum;
  }
  const achieved = barKg + (side - left) * 2;
  return { perSide, achieved, exact: Math.abs(left) < 1e-9, short: left * 2, bar: barKg };
}
/* Every weight the inventory can build, for "nearest loadable" answers. */
function loadableWeights(barKg, inv) {
  let sums = [0];
  inv.forEach(p => {
    const next = new Set(sums);
    sums.forEach(s => { for (let n = 1; n <= p.pairs; n++) next.add(s + n * p.kg); });
    sums = [...next];
  });
  return sums.map(s => barKg + s * 2).sort((a, b) => a - b);
}
function nearestLoadable(targetKg, barKg, inv) {
  const all = loadableWeights(barKg, inv);
  let below = null, above = null;
  for (const w2 of all) {
    if (w2 <= targetKg + 1e-9) below = w2;
    if (w2 >= targetKg - 1e-9) { above = w2; break; }
  }
  return { below, above };
}
const PLATE_COLOR = {
  25: '#c8102e', 20: '#1f57c3', 15: '#e8b923', 10: '#4fb477',
  5: '#e8ecf3', 2.5: '#c8102e', 1.25: '#8a93a5', 0.5: '#8a93a5',
};
export function openPlates(targetKg, presetBar, leaf) {
  /* A Smith load already includes the carriage, so the plate maths has to
     subtract it rather than a 20 kg barbell — otherwise it tells you to hang
     the carriage's weight in plates. */
  const smith = leaf && leaf.equipment === 'smith';
  if (smith && !(S.settings.smithKg > 0)) {
    return modal({
      title: 'Smith carriage weight',
      body: `<div class="sub" style="margin-top:0">Your Smith loads include the carriage, so working out the plates needs its weight. Carriages vary between about 7 and 25 kg — check the sticker, or weigh the empty bar.</div>
        <div class="field" style="margin-top:12px"><label>Carriage weight (${U()})</label>
          <input type="number" step="0.5" inputmode="decimal" id="smKg" placeholder="e.g. 15"></div>`,
      foot: `<button class="btn ghost" data-close>Not now</button><button class="btn primary" id="smSave">Save</button>`,
      onOpen: bg => { $('#smSave', bg).onclick = () => {
        const v = +$('#smKg', bg).value;
        if (!(v > 0)) return toast('Enter the carriage weight');
        S.settings.smithKg = toKg(v); save(); closeModal();
        openPlates(targetKg, presetBar, leaf);
      }; },
    });
  }
  /* The lift's own bar first (a trap bar for a trap-bar pull), then the rest
     of your bars to switch to. */
  const own = smith ? null : barFor(leaf);
  const bl = smith ? [{ name: 'Smith carriage', kg: S.settings.smithKg }]
    : own && own.preset ? [own, ...bars()] : bars();
  let barIdx = smith ? 0 : presetBar ? Math.max(0, bl.findIndex(b => b.kg === presetBar))
    : Math.max(0, bl.findIndex(b => b.name === own.name && b.kg === own.kg));
  const collars = smith ? 0 : collarPair();

  const draw = () => {
    const bar = { ...bl[barIdx], kg: bl[barIdx].kg + collars };   // collars ride on the bar
    const inv = inventory();
    const r = loadPlates(targetKg, bar.kg, inv);

    if (r.impossible === 'under') {
      return `<div class="sub">${wt(targetKg)} is below the ${esc(bar.name)} at ${wt(bar.kg)}.</div>`;
    }

    const stack = r.perSide.length
      ? r.perSide.map(p => `<div class="row" style="gap:9px;align-items:center;padding:6px 0">
          <div style="width:34px;height:34px;border-radius:7px;background:${PLATE_COLOR[p.kg] || '#8a93a5'};
            display:grid;place-items:center;font-size:11.5px;font-weight:800;color:${p.kg === 5 ? '#14181d' : '#fff'}">${dw(p.kg, 2)}</div>
          <div class="grow"><b>${dw(p.kg, 2)}${U()}</b> <span class="sub">× ${p.count} per side</span></div>
          <div class="mono sub">${nice(dw(p.kg * p.count * 2))}</div>
        </div>`).join('')
      : `<div class="sub">Empty bar.</div>`;

    let warn = '';
    if (!r.exact) {
      const n = nearestLoadable(targetKg, bar.kg, inv);
      warn = `<div style="border-left:3px solid var(--gold);background:rgba(255,197,66,.08);border-radius:0 10px 10px 0;padding:10px 13px;margin-bottom:10px">
        <b>Not loadable.</b> <span class="sub">Your inventory reaches ${wt(r.achieved)} — ${wt(r.short)} short.
        Nearest you can build: ${n.below ? wt(n.below) : '—'}${n.above && n.above !== r.achieved ? ` or ${wt(n.above)}` : ''}.</span></div>`;
    }

    return `${warn}
      ${bl[barIdx].preset ? `<div class="sub" style="margin-bottom:8px">${esc(bl[barIdx].name)} taken as ${wt(bl[barIdx].kg)} — add yours in Settings → Bars if it differs.</div>` : ''}
      ${collars ? `<div class="sub" style="margin-bottom:8px">Includes collars, ${wt(collars / 2)} each.</div>` : ''}
      <div class="row between" style="margin-bottom:8px">
        <div><div class="eyebrow">Per side</div>
          <div class="mono" style="font-size:30px;font-weight:800;line-height:1.1">${dw((r.achieved - bar.kg) / 2, 2)}</div></div>
        <div class="right"><div class="eyebrow">Total on bar</div>
          <div class="mono" style="font-size:30px;font-weight:800;line-height:1.1;color:${r.exact ? 'var(--green)' : 'var(--gold)'}">${dw(r.achieved, 2)}</div></div>
      </div>
      ${stack}`;
  };

  modal({
    title: `Plates · ${wt(targetKg)}`,
    body: `${bl.length > 1 ? `<div class="seg" id="pBars" style="margin-bottom:11px">
        ${bl.map((b, i) => `<button data-bar="${i}" class="${i === barIdx ? 'on' : ''}">${esc(b.name)} ${nice(dw(b.kg))}</button>`).join('')}
      </div>` : `<div class="sub" style="margin-bottom:9px">${esc(bl[0].name)} at ${wt(bl[0].kg)}</div>`}
      <div id="pOut">${draw()}</div>`,
    foot: `${leaf ? '<button class="btn ghost" id="pRamp">▲ Ramp to this</button>' : ''}<button class="btn primary" data-close>Done</button>`,
    onOpen: bg => {
      const rampBtn = $('#pRamp', bg);
      if (rampBtn) rampBtn.onclick = () => { closeModal(); openRamp(leafKey(leaf), targetKg); };
      bg.querySelectorAll('[data-bar]').forEach(b => b.onclick = () => {
        barIdx = +b.dataset.bar;
        if (!bl[barIdx].preset && !bl[barIdx].eq) { S.settings.barKg = bl[barIdx].kg; save(); }
        bg.querySelectorAll('[data-bar]').forEach(x => x.classList.toggle('on', +x.dataset.bar === barIdx));
        $('#pOut', bg).innerHTML = draw();
      });
    },
  });
}
/* ---------------- PLACES (D6) ----------------
   Named places with their kit, and optionally their own bars and plates.
   No places = everything available, as before. r&d/specs/places-spec.md. */
export const PLACE_PRESETS = [
  { name: 'Home gym', kit: ['barbell', 'dumbbells', 'kettlebell', 'plate', 'resistance_band'] },
  { name: 'Commercial gym', kit: ['barbell', 'dumbbells', 'kettlebell', 'trap_bar', 'smith', 'machine', 'plate_loaded_machine', 'cable', 'resistance_band', 'plate'] },
  { name: 'Hotel / travel', kit: ['dumbbells', 'machine', 'cable', 'resistance_band'] },
  { name: 'Strongman gym', kit: null },   // null = the whole vocabulary
];
export function places() { return S.settings.places || []; }
/* Any equipment of this movement is here. */
export function movableHere(leaf) {
  if (!curPlace() || !leaf) return true;
  const m = movementById(leaf.movement);
  return kitHas(leaf.equipment) || !!(m && (m.equipment || []).some(v => kitHas(v)));
}
export function curPlace() {
  const id = S.active && S.active.place !== undefined ? S.active.place : S.settings.place;
  return id ? places().find(p => p.id === id) || null : null;
}
/* Pocket kit travels with the lifter: a gripper or a finger band is never
   "not at" a place, so it never raises the missing-kit warning. */
const POCKET_KIT = ['gripper', 'extension_band'];
export function kitHas(eq, pl = curPlace()) { return !pl || !eq || eq === 'bodyweight' || POCKET_KIT.includes(eq) || (pl.kit || []).includes(eq); }
export function leafHere(leaf) { return !leaf || kitHas(leaf.equipment); }
/* The same movement with equipment that is here, keeping the execution when
   the new equipment allows it. */
export function placeSwap(leaf) {
  const m = leaf && movementById(leaf.movement);
  if (!m) return null;
  const eq = (m.equipment || []).find(v => v !== leaf.equipment && kitHas(v));
  if (!eq) return null;
  return completeLeaf(m, { equipment: eq, ...((m.execution || []).includes(leaf.execution) ? { execution: leaf.execution } : {}) });
}
export function placeName(pl = curPlace()) { return pl ? pl.name : ''; }
/* Live card: this exercise needs kit that isn't here. */
export function placeWarn(e, ei) {
  if (!e.leaf || leafHere(e.leaf)) return '';
  const sw = placeSwap(e.leaf);
  return `<div class="placewarn" role="note"><span class="grow">Needs ${esc(EQ_TITLE[e.leaf.equipment] || e.leaf.equipment)} — not at ${esc(placeName())}.</span>
    ${sw ? `<button class="btn xs primary" data-place-swap="${ei}">Swap to ${esc(EQ_TITLE[sw.equipment] || sw.equipment)}</button>` : '<span class="sub">No other kit for this here</span>'}</div>`;
}
export function swapForPlace(e) {
  const sw = placeSwap(e.leaf);
  if (!sw) return false;
  e.leaf = sw; e.legacyName = displayName(sw);
  delete e.auto;
  e.sets.forEach(s => { if (!s.done) { s.w = 0; delete s.auto; delete s.planW; if (s.sides) { s.sides.L.w = s.sides.R.w = 0; s.sides.at = [0, s.r || 0]; } } });
  return true;
}
export function placeChip() {
  if (!places().length) return '';
  const pl = curPlace(), need = S.active ? S.active.exercises.filter(e => e.leaf && !leafHere(e.leaf)).length : 0;
  return `<div class="row" style="gap:8px;align-items:center">
    <button class="btn xs ghost" id="placeBtn" aria-label="Where you're training: ${esc(pl ? pl.name : 'anywhere')}. Change">📍 ${esc(pl ? pl.name : 'Anywhere')} ▾</button>
    ${need ? `<span class="sub" style="color:var(--gold)">${need} exercise${need === 1 ? ' needs' : 's need'} kit that isn't here</span>` : ''}</div>`;
}
export function openPlacePick(after) {
  const cur = curPlace();
  modal({
    title: 'Where are you training?',
    body: `${places().map(p => `<button class="axrow ${cur && cur.id === p.id ? 'on' : ''}" data-pl-pick="${esc(p.id)}"><span class="lbl">${esc(p.name)} <span class="dimmer">${kitSummary(p)}</span></span><span class="rad"></span></button>`).join('')}
      <button class="axrow ${cur ? '' : 'on'}" data-pl-pick=""><span class="lbl">Anywhere <span class="dimmer">no filter</span></span><span class="rad"></span></button>`,
    foot: `<button class="btn ghost" id="plMng">Manage places</button><button class="btn primary" data-close>Done</button>`,
    onOpen: bg => {
      bg.querySelectorAll('[data-pl-pick]').forEach(b => b.onclick = () => {
        const id = b.dataset.plPick || null;
        if (S.active) S.active.place = id;
        S.settings.place = id;
        save(); closeModal(); if (after) after();
      });
      $('#plMng', bg).onclick = () => { closeModal(); openPlaces(); };
    },
  });
}
function kitSummary(p) {
  const all = catalogue().V.equipment || [];
  const n = (p.kit || []).filter(k => k !== 'bodyweight').length, of = all.filter(k => k !== 'bodyweight').length;
  return `${n === of ? 'all kit' : `${n} kinds of kit`}${p.plates && p.plates.length ? ' · own plates' : ''}`;
}
export function openPlaces() {
  const list = places();
  modal({
    title: 'Places',
    body: `<div class="sub" style="margin-bottom:10px">The kit where you train. The exercise picker greys what isn't there, and planned sessions offer a swap.</div>
      ${list.length ? list.map(p => `<div class="card tight row between" style="margin-bottom:8px;gap:8px">
          <div class="grow"><div style="font-weight:650">${esc(p.name)}${S.settings.place === p.id ? ' <span class="chip">current</span>' : ''}</div><div class="sub">${kitSummary(p)}</div></div>
          <button class="btn sm ghost" data-pl-edit="${esc(p.id)}">Edit</button></div>`).join('') : '<div class="empty">No places yet.</div>'}
      <div class="eyebrow" style="margin:12px 0 6px">Add a place</div>
      <div class="row wrap" style="gap:6px">${PLACE_PRESETS.map((p, i) => `<button class="btn sm ghost" data-pl-new="${i}">+ ${esc(p.name)}</button>`).join('')}
        <button class="btn sm ghost" data-pl-new="-1">+ Blank</button></div>`,
    foot: `<button class="btn primary" data-close>Done</button>`,
    onOpen: bg => {
      bg.querySelectorAll('[data-pl-edit]').forEach(b => b.onclick = () => { closeModal(); openPlaceEdit(places().find(p => p.id === b.dataset.plEdit)); });
      bg.querySelectorAll('[data-pl-new]').forEach(b => b.onclick = () => {
        const pr = PLACE_PRESETS[+b.dataset.plNew];
        const all = catalogue().V.equipment || [];
        closeModal();
        openPlaceEdit({ id: uid(), name: pr ? pr.name : '', kit: ['bodyweight', ...(pr ? (pr.kit || all) : [])].filter((v, i, a) => a.indexOf(v) === i), isNew: true });
      });
    },
  });
}
function openPlaceEdit(src) {
  if (!src) return;
  const p = structuredClone(src);
  const all = catalogue().V.equipment || [];
  const kit = new Set(p.kit || []);
  let own = !!(p.plates && p.plates.length);
  const invRows = () => `
      <div class="eyebrow" style="margin:10px 0 6px">Bars here</div>
      <div id="peBars">${(p.bars && p.bars.length ? p.bars : mainBars()).map((b, i) => barRow(i, b)).join('')}</div>
      <button class="btn xs ghost" id="peAddBar">+ Add bar</button>
      <div class="eyebrow" style="margin:12px 0 6px">Plates here — pairs</div>
      <div id="pePlates">${(p.plates && p.plates.length ? p.plates : mainPlates()).map((x, i) => plateRowHtml(i, x)).join('')}</div>
      <button class="btn xs ghost" id="peAddPlate">+ Add plate</button>
      <div class="field" style="margin-top:10px"><label for="peCollar">Collars — each (${U()})</label>
        <input type="number" step="0.25" inputmode="decimal" id="peCollar" value="${(p.plates && p.plates.length ? p.collarKg : S.settings.collarKg) > 0 ? dw(p.plates && p.plates.length ? p.collarKg : S.settings.collarKg, 2) : ''}" placeholder="0" style="width:120px"></div>`;
  modal({
    title: src.isNew ? 'New place' : `Edit · ${src.name}`,
    body: `<div class="field"><label for="peName">Name</label><input id="peName" value="${esc(p.name)}" placeholder="Home, Gym, Mum's garage…" maxlength="30"></div>
      <div class="eyebrow" style="margin:6px 0 6px">Kit here</div>
      <div id="peKit">${all.map(v => `<button class="axrow ${v === 'bodyweight' || kit.has(v) ? 'on' : ''} ${v === 'bodyweight' ? 'off' : ''}" data-pe-kit="${esc(v)}" ${v === 'bodyweight' ? 'disabled' : ''} aria-pressed="${v === 'bodyweight' || kit.has(v) ? 'true' : 'false'}">${EQ_ICON[v] || ''}<span class="lbl">${esc(EQ_TITLE[v] || v)}${v === 'bodyweight' ? ' <span class="dimmer">always</span>' : ''}</span><span class="rad"></span></button>`).join('')}</div>
      <div class="hr"></div>
      <button class="btn sm wide ${own ? 'primary' : 'ghost'}" id="peOwn" aria-pressed="${own}">${own ? '✓ Own bars and plates here' : 'Use the main bars and plates'}</button>
      <div class="sub" style="margin-top:4px">Turn on if the plates here differ — the calculator then loads from these.</div>
      <div id="peInv">${own ? invRows() : ''}</div>`,
    foot: `${src.isNew ? '' : '<button class="btn danger" id="peDel">Delete</button>'}<button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="peSave">Save</button>`,
    onOpen: bg => {
      bg.querySelectorAll('[data-pe-kit]').forEach(b => b.onclick = () => {
        const v = b.dataset.peKit;
        if (kit.has(v)) kit.delete(v); else kit.add(v);
        b.classList.toggle('on', kit.has(v)); b.setAttribute('aria-pressed', kit.has(v) ? 'true' : 'false');
      });
      const wireInv = () => {
        const addRow = (host, html) => { const d = document.createElement('div'); d.innerHTML = html; host.appendChild(d.firstElementChild); wireRm(); };
        const wireRm = () => bg.querySelectorAll('#peInv [data-brm], #peInv [data-prm]').forEach(b => b.onclick = () => b.closest('.row').remove());
        const ab = $('#peAddBar', bg), ap = $('#peAddPlate', bg);
        if (ab) ab.onclick = () => addRow($('#peBars', bg), barRow(`n${Date.now()}`, { name: '', kg: 0, eq: '' }));
        if (ap) ap.onclick = () => addRow($('#pePlates', bg), plateRowHtml(`n${Date.now()}`, { kg: 0, pairs: 1 }));
        wireRm();
      };
      $('#peOwn', bg).onclick = () => {
        own = !own;
        const b = $('#peOwn', bg);
        b.classList.toggle('primary', own); b.classList.toggle('ghost', !own); b.setAttribute('aria-pressed', own);
        b.textContent = own ? '✓ Own bars and plates here' : 'Use the main bars and plates';
        $('#peInv', bg).innerHTML = own ? invRows() : '';
        wireInv();
      };
      wireInv();
      const del = $('#peDel', bg);
      if (del) del.onclick = () => confirmDlg(`Delete ${src.name}? Sessions logged there keep their records.`, () => {
        S.settings.places = places().filter(x => x.id !== src.id);
        if (S.settings.place === src.id) S.settings.place = null;
        if (S.active && S.active.place === src.id) S.active.place = null;
        save(); bust(); closeAllModals(); render(); openPlaces();
      }, 'Delete');
      $('#peSave', bg).onclick = () => {
        const name = $('#peName', bg).value.trim();
        if (!name) return toast('Give the place a name');
        const out = { id: p.id, name, kit: ['bodyweight', ...all.filter(v => v !== 'bodyweight' && kit.has(v))], mt: Date.now() };   // mt: newest wins in Drive sync (4.5)
        if (own) {
          const nb = [...bg.querySelectorAll('#peInv [data-bn]')].map((el, i) => ({
            name: el.value.trim() || `Bar ${i + 1}`,
            kg: toKg(+bg.querySelector(`#peInv [data-bk="${el.dataset.bn}"]`).value || 0),
            eq: (bg.querySelector(`#peInv [data-be="${el.dataset.bn}"]`) || {}).value || '',
          })).filter(b => b.kg > 0).map(b => b.eq ? b : { name: b.name, kg: b.kg });
          const np = [...bg.querySelectorAll('#peInv [data-pk]')].map(el => ({
            kg: toKg(+el.value || 0),
            pairs: Math.max(0, +bg.querySelector(`#peInv [data-pp="${el.dataset.pk}"]`).value || 0),
          })).filter(x => x.kg > 0 && x.pairs > 0).sort((x, y) => y.kg - x.kg);
          if (!np.length) return toast('Add at least one plate, or use the main plates');
          out.plates = np;
          if (nb.length) out.bars = nb;
          const col = +$('#peCollar', bg).value;
          if (col > 0) out.collarKg = toKg(col);
        }
        const ls = places().slice(), i = ls.findIndex(x => x.id === p.id);
        if (i >= 0) ls[i] = out; else ls.push(out);
        S.settings.places = ls;
        if (!S.settings.place) S.settings.place = out.id;   // the first place becomes where you are
        save(); bust(); closeAllModals(); render(); openPlaces();
      };
    },
  });
}
function plateRowHtml(k, x) {
  return `<div class="row" style="gap:8px;margin-bottom:6px;align-items:center">
    <input type="number" step="0.25" inputmode="decimal" data-pk="${k}" value="${x.kg ? dw(x.kg, 2) : ''}" style="width:82px" aria-label="Plate size (${U()})">
    <span class="sub">${U()} ×</span>
    <input type="number" inputmode="numeric" data-pp="${k}" value="${x.pairs || 1}" style="width:64px" aria-label="Pairs of this plate">
    <span class="sub grow">pairs</span>
    <button class="btn sm ghost" data-prm="${k}" aria-label="Remove plate">−</button>
  </div>`;
}
/* The inverse of e1rm(): the load that makes `reps` at `rir` worth `e1`. */
export function loadFor(e1, reps, rir) {
  const eff = (reps || 0) + (rir || 0);
  return eff <= 1 ? e1 : e1 / (1 + Math.min(eff, 12) / 30);
}
export function roundLoadFor(kg, leaf) {
  /* Dumbbells and kettlebells step in 2 kg, or 5 lb for a lifter working in
     pounds (it used to be 2 kg either way: 44.1 lb — bug sweep 3.3). */
  if (leaf && (leaf.equipment === 'dumbbells' || leaf.equipment === 'kettlebell')) return U() === 'lb' ? toKg(Math.round(fromKg(kg) / 5) * 5) : Math.round(kg / 2) * 2;
  return roundBar(kg);
}
